  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Vorozole, a structurally analogous triazole aromatase inhibitor with two aryl substituents on the central carbon, showed excellent oral bioavailability in postmenopausal women, directly supporting high F for the query's similar azole/benzonitrile scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "MMV367, a triazole-containing drug, had an estimated human oral bioavailability of 90%, supporting high F for the query's azole-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Doravirine, which contains an azole and an aromatic nitrile, had a human oral bioavailability of 64%, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Orteronel, an azole-containing drug, had an estimated human F of 65%, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High: multiple high-transfer human bioavailability measurements for structurally related azole drugs (vorozole excellent, MMV367 90%, doravirine 64%, orteronel 65%) and favorable physicochemical properties support F>=20%; no evidence suggests low bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the supplied evidence",
    "Some records are estimates or absorption-based rather than formal absolute F",
    "Structural analogs differ in substituents (e.g., chloro vs cyano) but share the azole/aromatic core"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

